package au.com.roningroup.patrollink;
final class CaptureCatalog {
 static String wrap(String reader){reader=reader.trim();while(reader.endsWith(";"))reader=reader.substring(0,reader.length()-1);return "(function(){const docs=[document];for(let i=0;i<docs.length&&i<8;i++)for(const frame of docs[i].querySelectorAll('iframe,frame'))try{if(frame.contentDocument&&frame.contentDocument.body&&!docs.includes(frame.contentDocument))docs.push(frame.contentDocument);}catch{}const result={allRows:[],recognized:false,loading:false,login:false};const seen=new Set();const run=function(document,window){const getComputedStyle=e=>window.getComputedStyle(e);return ("+reader+");};for(const doc of docs){try{const data=JSON.parse(run(doc,doc.defaultView));result.recognized=result.recognized||data.recognized;result.login=result.login||data.login;for(const row of data.allRows||[]){const key=[row.id,row.guard,row.date].join('|');if(!seen.has(key)){seen.add(key);result.allRows.push(row);}}}catch{}const norm=x=>String(x||'').replace(/\\s+/g,' ').trim();\nfor(const table of doc.querySelectorAll('table,[role=\"grid\"]')){\n let headers=Array.from(table.querySelectorAll('thead tr:first-child th,thead tr:first-child td,[role=\"columnheader\"],tr:first-child th'));\n const map={};const names={id:['issueid','issuenumber','tracking'],issue:['reportedissue','issuetype','issue'],property:['propertyname','property','site'],date:['createddate','datecreated','reporteddate','issuedate'],guard:['createdby','reportedby','guard','officer']};\n headers.forEach((e,index)=>{let label=norm(e.getAttribute('data-field')||e.innerText||e.textContent).replace(/[^a-z]/gi,'').toLowerCase();for(const [field,aliases] of Object.entries(names))if(map[field]===undefined&&aliases.some(a=>label===a||(a!=='issue'&&label.startsWith(a))))map[field]=index;});\n if(map.id===undefined||map.issue===undefined)continue;\n for(const row of table.querySelectorAll('tr,[role=\"row\"]')){\n  if(row.closest('[data-trl-issue-hidden]'))continue;\n  const cells=Array.from(row.children).filter(e=>e.matches('td,[role=\"cell\"],[role=\"gridcell\"]'));\n  if(!cells[map.id]||!cells[map.issue])continue;\n  let hidden=false;for(let p=row;p&&p.nodeType===1;p=p.parentElement){const style=doc.defaultView.getComputedStyle(p);if(style.display==='none'||style.visibility==='hidden')hidden=true;}if(hidden)continue;\n  const value=field=>map[field]===undefined?'':norm(cells[map[field]]&&cells[map[field]].innerText||cells[map[field]]&&cells[map[field]].textContent);\n  const id=value('id'),issue=value('issue');\n  if(!/^(?:[0-9]{1,20}|[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i.test(id)||!/^parking\\s+breach\\b|^vehicle\\s+breach\\b|^parking\\s+violation\\b/i.test(issue))continue;\n  if(result.allRows.some(x=>x.id===id))continue;\n  result.allRows.push({id,issue,property:value('property'),date:value('date'),guard:value('guard')});result.recognized=true;\n }\n}}for(const doc of docs){result.loading=result.loading||Array.from(doc.querySelectorAll('.k-loading-mask,.rgLoading,.dataTables_processing,[aria-busy=\"true\"]')).some(e=>{for(let p=e;p&&p.nodeType===1;p=p.parentElement){const s=doc.defaultView.getComputedStyle(p);if(s.display==='none'||s.visibility==='hidden'||s.opacity==='0')return false;}return !!(e.offsetWidth||e.offsetHeight||e.getClientRects().length);});try{if(doc.defaultView.Sys&&doc.defaultView.Sys.WebForms)result.loading=result.loading||doc.defaultView.Sys.WebForms.PageRequestManager.getInstance().get_isInAsyncPostBack();}catch{}}result.login=result.login&&result.allRows.length===0;return JSON.stringify(result);})()";}
 private CaptureCatalog(){}
}
